window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-704f310fb3c34acb"]={"versions": [{"id": "FIG-704f310fb3c34acb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schnittstellendiagramm der AUTOSAR Adaptive Platform zur Darstellung der Abhängigkeiten des funktionalen Clusters <strong>Time Synchronization</strong> von externen Schnittstellen und Clustern innerhalb der Plattformarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Komponenten / Funktionale Cluster:</strong></p>\n<ul class=\"fig-list\"><li><code>Time Synchronization</code> («aapFunctionalCluster», daemon-based): Konsument aller definierten Schnittstellen über gestrichelte Abhängigkeitspfeile mit Stereotyp «use».\n</li><li><code>Operating System</code>: Realisiert über Realisierungspfeil (gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze) die Schnittstelle <code>Raw Socket API</code>.\n</li><li><code>Log and Trace</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Log and Trace::Logger</code>.\n</li><li><code>Persistency</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Persistency::KeyValueStorage</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen und Operationen:</strong></p>\n<ul class=\"fig-list\"><li><code>Raw Socket API</code> («aapInternal»): Betriebssystemnahe Schnittstelle ohne explizit aufgelistete Methoden.\n</li><li><code>Log and Trace::Logger</code> («aapAPI,aapNativeInterface»):\n<ul class=\"fig-list\"><li><code>+ IsEnabled()</code>\n</li><li><code>+ Log(MsgId, Params)</code>\n</li><li><code>+ LogDebug(): LogStream</code>\n</li><li><code>+ LogError(): LogStream</code>\n</li><li><code>+ LogFatal(): LogStream</code>\n</li><li><code>+ LogInfo(): LogStream</code>\n</li><li><code>+ LogVerbose(): LogStream</code>\n</li><li><code>+ LogWarn(): LogStream</code>\n</li><li><code>+ WithLevel(): LogStream</code>\n</li></ul>\n</li><li><code>Persistency::KeyValueStorage</code> («aapAPI,aapPortInterface»):\n<ul class=\"fig-list\"><li><code>+ DiscardPendingChanges()</code>\n</li><li><code>+ GetAllKeys()</code>\n</li><li><code>+ GetValue()</code>\n</li><li><code>+ KeyExists()</code>\n</li><li><code>+ RecoverKey()</code>\n</li><li><code>+ RemoveAllKeys()</code>\n</li><li><code>+ RemoveKey()</code>\n</li><li><code>+ ResetKey()</code>\n</li><li><code>+ SetValue()</code>\n</li><li><code>+ SyncToStorage()</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne Darstellung von Laufzeitsequenzen oder Protokollabläufen. Die gerichteten «use»-Abhängigkeiten modellieren synchrone bzw. funktionale Aufrufbeziehungen vom <code>Time Synchronization</code>-Daemon in Richtung der Schnittstellen des Betriebssystems (<code>Raw Socket API</code> für Netzwerkzeit-Paketübertragung), des Loggings (<code>Logger</code> für Status- und Fehlerausgaben) und der Zustandsspeicherung (<code>KeyValueStorage</code> für persistente Zeitsynchronisationsparameter).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Time Synchronization</code> ist architektonisch als Daemon-basierter Cluster konzipiert.\n</li><li>Zur Netzwerkanbindung für Zeitsynchronisationsprotokolle (z. B. gPTP/IEEE 802.1AS) greift der Daemon direkt auf interne Raw-Sockets des Betriebssystems (<code>Raw Socket API</code>) zu.\n</li><li><code>KeyValueStorage</code> wird über ein Service- bzw. Port-Interface («aapPortInterface») angebunden, während das Logging über eine plattformnative C++-API («aapNativeInterface») erfolgt.\n</li></ul>"}, {"id": "FIG-9230af3e70a5249a", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schnittstellendiagramm der AUTOSAR Adaptive Platform zur Darstellung der Abhängigkeiten des funktionalen Clusters <strong>Time Synchronization</strong> von externen Schnittstellen und Clustern innerhalb der Plattformarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Komponenten / Funktionale Cluster:</strong></p>\n<ul class=\"fig-list\"><li><code>Time Synchronization</code> («aapFunctionalCluster», daemon-based): Konsument aller definierten Schnittstellen über gestrichelte Abhängigkeitspfeile mit Stereotyp «use».\n</li><li><code>Operating System</code>: Realisiert über Realisierungspfeil (gestrichelte Linie mit geschlossener, nicht ausgefüllter Dreiecksspitze) die Schnittstelle <code>Raw Socket API</code>.\n</li><li><code>Log and Trace</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Log and Trace::Logger</code>.\n</li><li><code>Persistency</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Persistency::KeyValueStorage</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen und Operationen:</strong></p>\n<ul class=\"fig-list\"><li><code>Raw Socket API</code> («aapInternal»): Betriebssystemnahe Schnittstelle ohne explizit aufgelistete Methoden.\n</li><li><code>Log and Trace::Logger</code> («aapAPI,aapNativeInterface»):\n<ul class=\"fig-list\"><li><code>+ IsEnabled()</code>\n</li><li><code>+ Log(MsgId, Params)</code>\n</li><li><code>+ LogDebug(): LogStream</code>\n</li><li><code>+ LogError(): LogStream</code>\n</li><li><code>+ LogFatal(): LogStream</code>\n</li><li><code>+ LogInfo(): LogStream</code>\n</li><li><code>+ LogVerbose(): LogStream</code>\n</li><li><code>+ LogWarn(): LogStream</code>\n</li><li><code>+ WithLevel(): LogStream</code>\n</li></ul>\n</li><li><code>Persistency::KeyValueStorage</code> («aapAPI,aapPortInterface»):\n<ul class=\"fig-list\"><li><code>+ DiscardPendingChanges()</code>\n</li><li><code>+ GetAllKeys()</code>\n</li><li><code>+ GetValue()</code>\n</li><li><code>+ KeyExists()</code>\n</li><li><code>+ RecoverKey()</code>\n</li><li><code>+ RemoveAllKeys()</code>\n</li><li><code>+ RemoveKey()</code>\n</li><li><code>+ ResetKey()</code>\n</li><li><code>+ SetValue()</code>\n</li><li><code>+ SyncToStorage()</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne Darstellung von Laufzeitsequenzen oder Protokollabläufen. Die gerichteten «use»-Abhängigkeiten modellieren synchrone bzw. funktionale Aufrufbeziehungen vom <code>Time Synchronization</code>-Daemon in Richtung der Schnittstellen des Betriebssystems (<code>Raw Socket API</code> für Netzwerkzeit-Paketübertragung), des Loggings (<code>Logger</code> für Status- und Fehlerausgaben) und der Zustandsspeicherung (<code>KeyValueStorage</code> für persistente Zeitsynchronisationsparameter).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Time Synchronization</code> ist architektonisch als Daemon-basierter Cluster konzipiert.\n</li><li>Zur Netzwerkanbindung für Zeitsynchronisationsprotokolle (z. B. gPTP/IEEE 802.1AS) greift der Daemon direkt auf interne Raw-Sockets des Betriebssystems (<code>Raw Socket API</code>) zu.\n</li><li><code>KeyValueStorage</code> wird über ein Service- bzw. Port-Interface («aapPortInterface») angebunden, während das Logging über eine plattformnative C++-API («aapNativeInterface») erfolgt.\n</li></ul>"}, {"id": "FIG-9002b7d402773fe9", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schnittstellendiagramm der AUTOSAR Adaptive Platform zur Darstellung der Abhängigkeiten des funktionalen Clusters <strong>Time Synchronization</strong> von externen Schnittstellen, Plattform-Clustern und kryptografischen Diensten innerhalb der Plattformarchitektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Komponenten / Funktionale Cluster:</strong></p>\n<ul class=\"fig-list\"><li><code>Time Synchronization</code> («aapFunctionalCluster», daemon-based): Verwendet die Schnittstellen über «use»-Abhängigkeiten; an der Verbindung zu <code>KeyValueStorage</code> ist zusätzlich der Stereotyp «aapRequiredPort» annotiert.\n</li><li><code>Operating System</code>: Realisiert die Schnittstelle <code>Raw Socket API</code>.\n</li><li><code>Log and Trace</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Logger</code>.\n</li><li><code>Persistency</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>KeyValueStorage</code>.\n</li><li><code>Cryptography</code> («aapFunctionalCluster», daemon-based): Realisiert die Schnittstelle <code>CryptoStack</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen und Operationen:</strong></p>\n<ul class=\"fig-list\"><li><code>Raw Socket API</code> («aapInternal»): Interne OS-Schnittstelle ohne aufgeführte Methoden.\n</li><li><code>Logger</code> («aapAPI,aapNativeInterface»):\n<ul class=\"fig-list\"><li><code>+ IsEnabled(): bool</code>\n</li><li><code>+ Log(MsgId, Params)</code>\n</li><li><code>+ LogDebug(): LogStream</code>\n</li><li><code>+ LogError(): LogStream</code>\n</li><li><code>+ LogFatal(): LogStream</code>\n</li><li><code>+ LogInfo(): LogStream</code>\n</li><li><code>+ LogVerbose(): LogStream</code>\n</li><li><code>+ LogWarn(): LogStream</code>\n</li><li><code>+ WithLevel(): LogStream</code>\n</li></ul>\n</li><li><code>KeyValueStorage</code> («aapAPI,aapPortInterface»):\n<ul class=\"fig-list\"><li><code>+ DiscardPendingChanges()</code>\n</li><li><code>+ GetAllKeys()</code>\n</li><li><code>+ GetCurrentValueSize()</code>\n</li><li><code>+ GetValue()</code>\n</li><li><code>+ KeyExists()</code>\n</li><li><code>+ RecoverKey()</code>\n</li><li><code>+ RemoveAllKeys()</code>\n</li><li><code>+ RemoveKey()</code>\n</li><li><code>+ ResetKey()</code>\n</li><li><code>+ SetValue()</code>\n</li><li><code>+ SyncToStorage()</code>\n</li></ul>\n</li><li><code>CryptoStack</code> («aapAPI,aapNativeInterface»): Native Kryptografie-Schnittstelle ohne explizit aufgelistete Methoden.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne Darstellung von Laufzeitsequenzen oder Protokollabläufen. Die gerichteten «use»-Abhängigkeiten modellieren synchrone bzw. funktionale Aufrufbeziehungen vom <code>Time Synchronization</code>-Daemon in Richtung der Schnittstellen des Betriebssystems (<code>Raw Socket API</code> für Netzwerkzeit-Paketübertragung), des Loggings (<code>Logger</code> für Status- und Fehlerausgaben) und der Zustandsspeicherung (<code>KeyValueStorage</code> für persistente Zeitsynchronisationsparameter).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Time Synchronization</code> setzt für kryptografische Funktionen (z. B. Authentifizierung und Absicherung von Zeitprotokollnachrichten) auf die native Schnittstelle <code>CryptoStack</code> des Daemon-basierten Clusters <code>Cryptography</code>.\n</li><li>Der Zugriff auf <code>KeyValueStorage</code> ist formal als Port-Interface über einen Required Port («aapRequiredPort») modelliert.\n</li><li>Die Methode <code>GetCurrentValueSize()</code> ermöglicht die Bestimmung von Nutzdatengrößen vor dem Auslesen aus dem persistenten Speicher.\n</li><li><code>IsEnabled(): bool</code> spezifiziert explizit einen booleschen Rückgabewert zur Prüfung des Logging-Zustands.\n</li></ul>"}, {"id": "FIG-4975a7f23e5f4a80", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schnittstellendiagramm der AUTOSAR Adaptive Platform zur Darstellung der Abhängigkeiten des funktionalen Clusters <strong>Time Synchronization</strong> von Betriebs-, Persistenz-, Logging-, Krypto- und Ausführungsmanagement-Diensten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Komponenten / Funktionale Cluster:</strong></p>\n<ul class=\"fig-list\"><li><code>Time Synchronization</code> («aapFunctionalCluster», daemon-based): Verwendet alle Schnittstellen über «use»-Abhängigkeiten; an der Beziehung zu <code>KeyValueStorage</code> ist «aapRequiredPort» annotiert.\n</li><li><code>Operating System</code>: Realisiert die Schnittstelle <code>Raw Socket API</code>.\n</li><li><code>Log and Trace</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>Logger</code>.\n</li><li><code>Execution Management</code> («aapFunctionalCluster», daemon-based): Realisiert die Schnittstelle <code>ExecutionClient</code>.\n</li><li><code>Persistency</code> («aapFunctionalCluster»): Realisiert die Schnittstelle <code>KeyValueStorage</code>.\n</li><li><code>Cryptography</code> («aapFunctionalCluster», daemon-based): Realisiert die Schnittstelle <code>CryptoStack</code>.\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen und Operationen:</strong></p>\n<ul class=\"fig-list\"><li><code>Raw Socket API</code> («aapInternal»): Interne OS-Schnittstelle ohne deklarierte Operationen.\n</li><li><code>Logger</code> («aapAPI,aapNativeInterface»):\n<ul class=\"fig-list\"><li><code>+ IsEnabled(): bool</code>\n</li><li><code>+ Log(MsgId, Params)</code>\n</li><li><code>+ LogDebug(): LogStream</code>\n</li><li><code>+ LogError(): LogStream</code>\n</li><li><code>+ LogFatal(): LogStream</code>\n</li><li><code>+ LogInfo(): LogStream</code>\n</li><li><code>+ LogVerbose(): LogStream</code>\n</li><li><code>+ LogWarn(): LogStream</code>\n</li><li><code>+ WithLevel(): LogStream</code>\n</li></ul>\n</li><li><code>ExecutionClient</code> («aapAPI,aapNativeInterface»):\n<ul class=\"fig-list\"><li><code>+ Create()</code> (statische Methode / Factory)\n</li><li><code>+ ReportExecutionState(ExecutionState)</code>\n</li></ul>\n</li><li><code>KeyValueStorage</code> («aapAPI,aapPortInterface»):\n<ul class=\"fig-list\"><li><code>+ DiscardPendingChanges()</code>\n</li><li><code>+ GetAllKeys()</code>\n</li><li><code>+ GetCurrentValueSize()</code>\n</li><li><code>+ GetValue()</code>\n</li><li><code>+ KeyExists()</code>\n</li><li><code>+ RecoverKey()</code>\n</li><li><code>+ RemoveAllKeys()</code>\n</li><li><code>+ RemoveKey()</code>\n</li><li><code>+ ResetKey()</code>\n</li><li><code>+ SetValue()</code>\n</li><li><code>+ SyncToStorage()</code>\n</li></ul>\n</li><li><code>CryptoStack</code> («aapAPI,aapNativeInterface»): Native Kryptografie-Schnittstelle ohne deklarierte Operationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architekturdiagramm ohne Darstellung von Laufzeitsequenzen oder Protokollabläufen. Die gerichteten «use»-Abhängigkeiten modellieren synchrone bzw. funktionale Aufrufbeziehungen vom <code>Time Synchronization</code>-Daemon in Richtung der Schnittstellen des Betriebssystems (<code>Raw Socket API</code> für Netzwerkzeit-Paketübertragung), des Loggings (<code>Logger</code> für Status- und Fehlerausgaben) und der Zustandsspeicherung (<code>KeyValueStorage</code> für persistente Zeitsynchronisationsparameter).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Time Synchronization</code> bindet als Daemon-basierte Adaptive Application / Functional Cluster den <code>ExecutionClient</code> des <code>Execution Management</code> ein, um den eigenen Lebenszyklus und Prozesszustand (<code>ReportExecutionState</code>) im System zu melden.\n</li><li><code>ExecutionClient::Create()</code> dient als Factory zur Instanziierung des Clients.\n</li><li>Der Cluster stützt sich neben <code>Execution Management</code> auf <code>Cryptography</code> (native Krypto-Dienste), <code>Persistency</code> (Port-basiert via <code>KeyValueStorage</code>), <code>Log and Trace</code> (natives Logging) sowie das Betriebssystem (<code>Raw Socket API</code>).\n</li></ul>"}], "trans": [{"from": "FIG-704f310fb3c34acb", "to": "FIG-9230af3e70a5249a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9230af3e70a5249a", "to": "FIG-9002b7d402773fe9", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung des Functional Clusters <code>Cryptography</code> (daemon-based, «aapFunctionalCluster») mit Realisierung der Schnittstelle <code>CryptoStack</code> («aapAPI,aapNativeInterface»).\n</li><li>Ergänzung der Abhängigkeit «use» von <code>Time Synchronization</code> auf <code>CryptoStack</code>.\n</li><li>Ergänzung des Stereotyps «aapRequiredPort» an der «use»-Abhängigkeit von <code>Time Synchronization</code> zu <code>KeyValueStorage</code>.\n</li><li>Schnittstelle <code>KeyValueStorage</code>: Methode <code>+ GetCurrentValueSize()</code> ergänzt; Klassenbezeichnung von <code>Persistency::KeyValueStorage</code> auf <code>KeyValueStorage</code> verkürzt.\n</li><li>Schnittstelle <code>Logger</code>: Methoden-Signatur von <code>+ IsEnabled()</code> zu <code>+ IsEnabled(): bool</code> präzisiert; Klassenbezeichnung von <code>Log and Trace::Logger</code> auf <code>Logger</code> verkürzt.\n</li></ul>"}, {"from": "FIG-9002b7d402773fe9", "to": "FIG-4975a7f23e5f4a80", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung des Functional Clusters <code>Execution Management</code> (daemon-based, «aapFunctionalCluster»).\n</li><li>Ergänzung der Schnittstelle <code>ExecutionClient</code> («aapAPI,aapNativeInterface») mit statischer Factory-Methode <code>+ Create()</code> und Methode <code>+ ReportExecutionState(ExecutionState)</code>.\n</li><li>Ergänzung der Realisierungsbeziehung von <code>Execution Management</code> zu <code>ExecutionClient</code>.\n</li><li>Ergänzung der Abhängigkeit «use» von <code>Time Synchronization</code> auf <code>ExecutionClient</code>.\n</li></ul>"}]};
